#!/usr/bin/env node

/**
 * Hardcoded Value Detector
 * Scans JavaScript files for values that should be environment variables
 */

const fs = require('fs');
const path = require('path');

// Patterns to detect hardcoded values that should be environment variables
const DETECTION_PATTERNS = {
  // Port numbers (common server ports)
  ports: /\b(?:3000|8080|80|443|5432|27017|6379|9200)\b/,

  // Common configuration values
  booleans: /\b(?:true|false)\b/gi,

  // Common strings that might be configurable
  configStrings: /\b(?:production|development|test|staging|localhost)\b/gi,

  // IP addresses
  ipAddresses: /\b(?:\d{1,3}\.){3}\d{1,3}\b/,

  // URLs (could be configurable endpoints)
  urls: /https?:\/\/[^\s"'<>]+/gi,

  // Database connection patterns
  dbConnections: /\b(?:mongodb|postgres|mysql|redis):\/\/[^\s'"]+/gi,

  // Common numeric limits/timeouts
  numericConfigs: /\b(?:timeout|limit|max|min|retry|delay)\s*[:=]\s*\d+/gi,

  // API keys/credentials patterns (simplified)
  secretPatterns: /\b(?:key|secret|token|password|pass|pwd|credential|auth)\s*[:=]\s*['"][^'"]{10,}['"]/gi,
};

// Files to exclude from scanning
const EXCLUDE_PATTERNS = [
  /node_modules/,
  /\.git/,
  /package-lock\.json/,
  /yarn\.lock/,
  /\.min\.js$/,
];

// Severity levels
const SEVERITY = {
  CRITICAL: '🔴 CRITICAL',
  HIGH: '🟠 HIGH', 
  MEDIUM: '🟡 MEDIUM',
  LOW: '🟢 LOW',
  INFO: '🔵 INFO'
};

function scanFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n');
  const findings = [];

  lines.forEach((line, lineNumber) => {
    const lineNum = lineNumber + 1;

    // Check each pattern
    for (const [category, pattern] of Object.entries(DETECTION_PATTERNS)) {
      const matches = line.match(pattern);
      if (matches) {
        matches.forEach(match => {
          // Clean up the match for display
          const cleanMatch = match.length > 50 ? match.substring(0, 50) + '...' : match;

          let severity = SEVERITY.INFO;
          let recommendation = 'Consider making this configurable';

          // Determine severity based on category
          switch(category) {
            case 'ports':
              severity = SEVERITY.HIGH;
              recommendation = 'Port numbers should be environment variables (e.g., process.env.PORT)';
              break;
            case 'secretPatterns':
              severity = SEVERITY.CRITICAL;
              recommendation = 'SECURITY RISK: Secrets should NEVER be hardcoded. Use environment variables immediately!';
              break;
            case 'dbConnections':
              severity = SEVERITY.HIGH;
              recommendation = 'Database connection strings should be environment variables';
              break;
            case 'ipAddresses':
              severity = SEVERITY.MEDIUM;
              recommendation = 'IP addresses should be configurable';
              break;
            case 'urls':
              severity = line.includes('localhost') ? SEVERITY.LOW : SEVERITY.MEDIUM;
              recommendation = 'Service URLs/endpoints should be configurable';
              break;
          }

          findings.push({
            file: filePath,
            line: lineNum,
            category,
            match: cleanMatch,
            severity,
            recommendation,
            context: line.trim()
          });
        });
      }
    }
  });

  return findings;
}

function scanDirectory(dirPath) {
  const allFindings = [];

  function walk(currentPath) {
    const items = fs.readdirSync(currentPath, { withFileTypes: true });

    for (const item of items) {
      const fullPath = path.join(currentPath, item.name);

      // Check if path should be excluded
      if (EXCLUDE_PATTERNS.some(pattern => pattern.test(fullPath))) {
        continue;
      }

      if (item.isDirectory()) {
        walk(fullPath);
      } else if (item.isFile() && /\.(js|ts|jsx|tsx|json)$/.test(item.name)) {
        try {
          const findings = scanFile(fullPath);
          allFindings.push(...findings);
        } catch (error) {
          console.error(`Error scanning ${fullPath}:`, error.message);
        }
      }
    }
  }

  walk(dirPath);
  return allFindings;
}

function printReport(findings) {
  console.log('\n' + '='.repeat(80));
  console.log('HARDCODED VALUES SECURITY SCAN REPORT');
  console.log('='.repeat(80));

  if (findings.length === 0) {
    console.log('\n✅ No hardcoded values detected that require immediate attention.');
    console.log('Note: This tool may not catch all patterns. Manual review is recommended.');
    return;
  }

  // Group by severity
  const bySeverity = {};
  findings.forEach(finding => {
    if (!bySeverity[finding.severity]) {
      bySeverity[finding.severity] = [];
    }
    bySeverity[finding.severity].push(finding);
  });

  // Print by severity (CRITICAL first)
  const severityOrder = [
    SEVERITY.CRITICAL,
    SEVERITY.HIGH, 
    SEVERITY.MEDIUM,
    SEVERITY.LOW,
    SEVERITY.INFO
  ];

  severityOrder.forEach(severity => {
    const severityFindings = bySeverity[severity];
    if (severityFindings && severityFindings.length > 0) {
      console.log(`\n${severity} - ${severityFindings.length} finding(s):`);
      console.log('-'.repeat(80));

      severityFindings.forEach(finding => {
        console.log(`\nFile: ${finding.file}:${finding.line}`);
        console.log(`Match: ${finding.match}`);
        console.log(`Context: ${finding.context}`);
        console.log(`Recommendation: ${finding.recommendation}`);
      });
    }
  });

  // Summary
  console.log('\n' + '='.repeat(80));
  console.log('SUMMARY');
  console.log('='.repeat(80));

  severityOrder.forEach(severity => {
    const count = bySeverity[severity]?.length || 0;
    if (count > 0) {
      console.log(`${severity}: ${count}`);
    }
  });

  console.log(`\nTotal findings: ${findings.length}`);

  // Recommendations
  console.log('\n' + '='.repeat(80));
  console.log('RECOMMENDATIONS');
  console.log('='.repeat(80));

  if (bySeverity[SEVERITY.CRITICAL]?.length > 0) {
    console.log('\n🚨 IMMEDIATE ACTION REQUIRED:');
    console.log('1. Remove all hardcoded secrets from code immediately');
    console.log('2. Store secrets in environment variables or secret management service');
    console.log('3. Rotate any exposed credentials');
  }

  if (bySeverity[SEVERITY.HIGH]?.length > 0) {
    console.log('\n🔧 HIGH PRIORITY FIXES:');
    console.log('1. Move port numbers, database URLs to environment variables');
    console.log('2. Use configuration files for environment-specific settings');
  }

  console.log('\n📝 GENERAL BEST PRACTICES:');
  console.log('1. Use environment variables for all configuration');
  console.log('2. Create .env.example with placeholder values');
  console.log('3. Add .env* to .gitignore');
  console.log('4. Use a configuration module to manage all settings');
}

// Run the scanner
const startDir = process.argv[2] || '.';
console.log(`Scanning directory: ${startDir}`);

try {
  const findings = scanDirectory(startDir);
  printReport(findings);

  // Save detailed report to file
  if (findings.length > 0) {
    const report = {
      timestamp: new Date().toISOString(),
      directory: startDir,
      findings: findings.map(f => ({
        file: f.file,
        line: f.line,
        category: f.category,
        match: f.match,
        severity: f.severity,
        recommendation: f.recommendation,
        context: f.context
      }))
    };

    fs.writeFileSync(
      'hardcoded_values_report.json',
      JSON.stringify(report, null, 2)
    );
    console.log('\n📄 Detailed report saved to: hardcoded_values_report.json');
  }
} catch (error) {
  console.error('Error during scan:', error.message);
  process.exit(1);
}

