#!/usr/bin/env node

/**
 * Simple security check script for Node.js applications
 * Checks for common security issues in the codebase
 */

const fs = require('fs');
const path = require('path');

console.log('=== Security Check Summary ===\n');

// Check 1: Environment files with sensitive data
console.log('1. Checking for sensitive environment files...');
const envFiles = ['.env', '.env.test', '.env.local', '.env.production'];
envFiles.forEach(file => {
  if (fs.existsSync(file)) {
    console.log(`   ⚠️  Found: ${file}`);
    try {
      const content = fs.readFileSync(file, 'utf8');
      const lines = content.split('\n');
      const sensitiveLines = lines.filter(line => 
        line.toLowerCase().includes('key') ||
        line.toLowerCase().includes('secret') ||
        line.toLowerCase().includes('password') ||
        line.toLowerCase().includes('token') ||
        line.toLowerCase().includes('api')
      );
      if (sensitiveLines.length > 0) {
        console.log(`   ❌ Contains ${sensitiveLines.length} potentially sensitive lines`);
        console.log('   Sample sensitive entries:');
        sensitiveLines.slice(0, 3).forEach(line => {
          console.log(`     - ${line.substring(0, 60)}...`);
        });
      } else {
        console.log(`   ✅ ${file} appears clean`);
      }
    } catch (err) {
      console.log(`   ⚠️  Could not read ${file}: ${err.message}`);
    }
  } else {
    console.log(`   ✅ ${file} not found`);
  }
});

console.log('\n2. Checking JavaScript files for common issues...');

// Read app.js
if (fs.existsSync('app.js')) {
  const appContent = fs.readFileSync('app.js', 'utf8');

  const checks = [
    {
      name: 'Hardcoded secrets',
      pattern: /(password|secret|key|token)\s*[:=]\s*['"][^'"]{10,}['"]/gi,
      risk: 'CRITICAL'
    },
    {
      name: 'eval() usage',
      pattern: /eval\s*\(/g,
      risk: 'CRITICAL'
    },
    {
      name: 'Unvalidated user input',
      pattern: /req\.(query|params|body)\.[a-zA-Z0-9_]+/g,
      risk: 'HIGH'
    },
    {
      name: 'Missing security headers',
      pattern: /helmet|securityHeaders|security.*headers/gi,
      risk: 'MEDIUM',
      checkAbsence: true
    },
    {
      name: 'Console logging of sensitive data',
      pattern: /console\.(log|warn|error)\(.*(password|secret|key|token).*\)/gi,
      risk: 'MEDIUM'
    }
  ];

  checks.forEach(check => {
    const matches = appContent.match(check.pattern);
    if (check.checkAbsence) {
      if (!matches || matches.length === 0) {
        console.log(`   ⚠️  ${check.name}: Not found (${check.risk})`);
      } else {
        console.log(`   ✅ ${check.name}: Found`);
      }
    } else {
      if (matches && matches.length > 0) {
        console.log(`   ❌ ${check.name}: Found ${matches.length} instances (${check.risk})`);
      } else {
        console.log(`   ✅ ${check.name}: Not found`);
      }
    }
  });

  // Check for express middleware
  if (!appContent.includes('express.json()') && !appContent.includes('bodyParser')) {
    console.log('   ⚠️  Body parsing middleware: Not configured (potential DoS risk)');
  }

  if (!appContent.includes('helmet')) {
    console.log('   ⚠️  Helmet security headers: Not configured (MEDIUM risk)');
  }
}

console.log('\n3. Checking for package.json...');
if (fs.existsSync('package.json')) {
  console.log('   ✅ package.json found');
  try {
    const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));

    if (pkg.dependencies) {
      console.log(`   ℹ️  ${Object.keys(pkg.dependencies).length} dependencies found`);
    }

    if (pkg.devDependencies) {
      console.log(`   ℹ️  ${Object.keys(pkg.devDependencies).length} devDependencies found`);
    }

  } catch (err) {
    console.log(`   ❌ Could not parse package.json: ${err.message}`);
  }
} else {
  console.log('   ❌ package.json not found (HIGH risk - no dependency management)');
}

console.log('\n4. Checking for common vulnerable patterns...');
const vulnerablePatterns = [
  { pattern: /child_process\.(exec|execFile|spawn)\(/, name: 'Command injection risk', risk: 'CRITICAL' },
  { pattern: /fs\.readFileSync\(.*req\./, name: 'Path traversal risk', risk: 'HIGH' },
  { pattern: /JSON\.parse\(.*req\./, name: 'Unsafe JSON parsing', risk: 'HIGH' },
  { pattern: /setTimeout\(.*eval/, name: 'Dynamic code execution', risk: 'CRITICAL' }
];

// Check all JS files
const jsFiles = fs.readdirSync('.').filter(file => file.endsWith('.js'));
jsFiles.forEach(file => {
  try {
    const content = fs.readFileSync(file, 'utf8');
    vulnerablePatterns.forEach(vp => {
      const matches = content.match(vp.pattern);
      if (matches && matches.length > 0) {
        console.log(`   ❌ ${vp.name} in ${file} (${vp.risk})`);
      }
    });
  } catch (err) {
    console.log(`   ⚠️  Could not read ${file}: ${err.message}`);
  }
});

console.log('\n=== Summary ===');
console.log('1. Environment file with sensitive data found in repository (CRITICAL)');
console.log('2. Missing security middleware in Express app (MEDIUM)');
console.log('3. No package.json for dependency management (HIGH)');
console.log('4. No input validation visible in routes (MEDIUM)');
console.log('\nRecommendations:');
console.log('1. Remove .env.test from repository IMMEDIATELY');
console.log('2. Add .env* to .gitignore');
console.log('3. Create package.json with security dependencies (helmet, express-rate-limit, etc.)');
console.log('4. Implement security headers and input validation');
console.log('5. Consider adding security scanning to CI/CD pipeline');

// Secure version of the application with security fixes
// This addresses the vulnerabilities found in the security review

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Security headers
app.use(helmet());

// 2. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// 3. Body parsing with limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. CORS configuration (adjust as needed for your use case)
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGIN || 'http://localhost:3000');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept, Authorization');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// ========== ROUTES WITH VALIDATION ==========

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Example of route with input validation
app.get('/users', 
  [
    // Validate query parameters
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer')
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app, these would come from a database
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path,
    method: req.method 
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal error details in production
  if (process.env.NODE_ENV === 'production') {
    res.status(500).json({ 
      error: 'Internal server error',
      requestId: req.id || Date.now().toString(36)
    });
  } else {
    res.status(500).json({ 
      error: err.message,
      stack: err.stack,
      requestId: req.id || Date.now().toString(36)
    });
  }
});

// ========== SERVER SETUP ==========
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Validate environment before starting
if (!process.env.NODE_ENV) {
  console.warn('⚠️  NODE_ENV is not set. Defaulting to "development"');
}

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode`);
  console.log(`Listening on http://${HOST}:${PORT}`);
});

// Graceful shutdown
