      region: process.env.AWS_REGION || 'us-east-1'
    }
  }
  */
};

// ========== VALIDATION ==========

/**
 * Validate required configuration for production
 */
function validateConfig() {
  const { nodeEnv } = config.server;

  // Configuration required for production
  if (nodeEnv === 'production') {
    const requiredInProduction = [
      // Add environment variables required in production
      // Example: 'DATABASE_URL'
    ];

    const missing = requiredInProduction.filter(envVar => !process.env[envVar]);

    if (missing.length > 0) {
      throw new Error(`Missing required environment variables in production: ${missing.join(', ')}`);
    }
  }

  // Warn about development defaults in production
  if (nodeEnv === 'production') {
    const devDefaults = [];

    if (config.security.cors.allowedOrigin.includes('localhost')) {
      devDefaults.push('CORS allowed origin includes localhost (consider restricting in production)');
    }

    if (config.security.rateLimit.max === 100) {
      devDefaults.push('Using default rate limit (consider adjusting for production)');
    }

    if (devDefaults.length > 0) {
      console.warn('⚠️ Production configuration using development defaults:');
      devDefaults.forEach(warning => console.warn(`  - ${warning}`));
    }
  }

  // Validate numeric values
  const numericValidations = [
    { value: config.server.port, min: 1, max: 65535, name: 'Port' },
    { value: config.security.rateLimit.windowMs, min: 1000, name: 'Rate limit window' },
    { value: config.security.rateLimit.max, min: 1, name: 'Rate limit max requests' },
    { value: config.app.validation.pagination.minLimit, min: 1, name: 'Pagination min limit' },
    { value: config.app.validation.pagination.maxLimit, min: 1, name: 'Pagination max limit' }
  ];

  numericValidations.forEach(({ value, min, max, name }) => {
    if (value < min) {
      throw new Error(`${name} must be at least ${min}, got ${value}`);
    }
    if (max && value > max) {
      throw new Error(`${name} must be at most ${max}, got ${value}`);
    }
  });

  console.log(`✅ Configuration validated for ${nodeEnv} environment`);
}

// ========== HELPER FUNCTIONS ==========

/**
 * Get server URL
 */
config.getServerUrl = function() {
  const { protocol, host, port } = this.server;
  return `${protocol}://${host}:${port}`;
};

/**
 * Check if running in production
 */
config.isProduction = function() {
  return this.server.nodeEnv === 'production';
};

/**
 * Check if running in development
 */
config.isDevelopment = function() {
  return this.server.nodeEnv === 'development';
};

/**
 * Check if running in test
 */
config.isTest = function() {
  return this.server.nodeEnv === 'test';
};

// Validate configuration on load
try {
  validateConfig();
} catch (error) {
  console.error(`❌ Configuration validation failed: ${error.message}`);
  if (config.isProduction()) {
    throw error;
  } else {
    console.warn('⚠️ Continuing with configuration despite validation warnings');
  }
}

module.exports = config;

// Secure version of the application with configuration management
// All configuration values come from environment variables via config.js

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const config = require('./config');

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Security headers
app.use(helmet());

// 2. Rate limiting using configuration
const limiter = rateLimit(config.security.rateLimit);
app.use(limiter);

// 3. Body parsing with configurable limits
app.use(express.json({ limit: config.security.bodyParser.jsonLimit }));
app.use(express.urlencoded({ 
  extended: config.security.bodyParser.urlencodedExtended, 
  limit: config.security.bodyParser.urlencodedLimit 
}));

// 4. CORS configuration from environment
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', config.security.cors.allowedOrigin);
  res.header('Access-Control-Allow-Headers', config.security.cors.allowedHeaders);
  res.header('Access-Control-Allow-Methods', config.security.cors.allowedMethods);
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// ========== ROUTES WITH VALIDATION ==========

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.server.nodeEnv,
    version: process.env.npm_package_version || '1.0.0'
  });
});

// Route with configurable validation
app.get('/users', 
  [
    // Validate query parameters using configurable limits
    body('limit').optional().isInt({ 
      min: config.app.validation.pagination.minLimit, 
      max: config.app.validation.pagination.maxLimit 
    }).withMessage(`Limit must be between ${config.app.validation.pagination.minLimit} and ${config.app.validation.pagination.maxLimit}`),

    body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),

    body('sort').optional().isIn(['name', 'id', 'email']).withMessage('Sort must be one of: name, id, email')
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Extract validated parameters
    const limit = parseInt(req.query.limit) || config.app.validation.pagination.defaultLimit;
    const offset = parseInt(req.query.offset) || 0;
    const sort = req.query.sort || 'id';

    // Demo data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01' },
      { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: '2024-01-02' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', createdAt: '2024-01-03' },
      { id: 4, name: 'Diana', email: 'diana@example.com', createdAt: '2024-01-04' },
    ];

    // Sort users
    const sortedUsers = [...users].sort((a, b) => {
      if (sort === 'name') return a.name.localeCompare(b.name);
      if (sort === 'email') return a.email.localeCompare(b.email);
      return a.id - b.id;
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(offset, offset + limit);

    res.json({
      users: paginatedUsers,
      pagination: {
        total: users.length,
        limit,
        offset,
        hasMore: offset + limit < users.length
      }
    });
  }
);

// Debug routes (enabled via configuration)
if (config.app.features.enableDebugRoutes) {
  app.get('/debug/config', (req, res) => {
    // Return sanitized configuration (never expose secrets!)
    const safeConfig = {
      server: config.server,
      security: {
        rateLimit: config.security.rateLimit,
        cors: config.security.cors,
        bodyParser: config.security.bodyParser
      },
      app: {
        validation: config.app.validation,
        features: config.app.features
      },
      logging: config.logging
    };

    res.json({
      config: safeConfig,
      environment: config.server.nodeEnv,
      timestamp: new Date().toISOString()
    });
  });

  app.get('/debug/health-detailed', (req, res) => {
    const health = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      nodeVersion: process.version,
      platform: process.platform,
      config: {
        nodeEnv: config.server.nodeEnv,
        port: config.server.port,
        rateLimitEnabled: true
      }
    };

    res.json(health);
  });
}

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error with sanitization
  const logEntry = {
    message: err.message,
    stack: config.isDevelopment() ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('User-Agent'),
    timestamp: new Date().toISOString()
  };

  // Redact sensitive information from logs
  if (config.logging.redact.enabled) {
    config.logging.redact.patterns.forEach(pattern => {
      if (logEntry.message) {
        logEntry.message = logEntry.message.replace(pattern, '$1=***REDACTED***');
      }
    });
  }

  console.error('Error:', logEntry);

  // Don't expose internal error details in production
  if (config.isProduction()) {
    res.status(500).json({ 
      error: 'Internal server error',
      requestId: req.id || Date.now().toString(36),
      timestamp: new Date().toISOString()
    });
  } else {
    res.status(500).json({ 
      error: err.message,
      stack: config.isDevelopment() ? err.stack : undefined,
      requestId: req.id || Date.now().toString(36),
      timestamp: new Date().toISOString()
    });
  }
});

// ========== SERVER SETUP ==========

const { port, host } = config.server;

const server = app.listen(port, host, () => {
  console.log(`🚀 Server started`);
  console.log(`   Environment: ${config.server.nodeEnv}`);
  console.log(`   Listening: ${config.getServerUrl()}`);
  console.log(`   Rate limiting: ${config.security.rateLimit.max} requests per ${config.security.rateLimit.windowMs / 60000} minutes`);
  console.log(`   Debug routes: ${config.app.features.enableDebugRoutes ? 'Enabled' : 'Disabled'}`);

  if (config.isDevelopment()) {
    console.log(`\n📋 Available routes:`);
    console.log(`   GET ${config.getServerUrl()}/health`);
    console.log(`   GET ${config.getServerUrl()}/users`);
    if (config.app.features.enableDebugRoutes) {
      console.log(`   GET ${config.getServerUrl()}/debug/config`);
      console.log(`   GET ${config.getServerUrl()}/debug/health-detailed`);
    }
  }
});

// ========== GRACEFUL SHUTDOWN ==========

const shutdown = async (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  // Stop accepting new connections
  server.close(() => {
    console.log('HTTP server closed');

    // Close database connections if any
    // await database.close();

    console.log('Graceful shutdown complete');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, config.app.timeouts.shutdownTimeout);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  shutdown('UNCAUGHT_EXCEPTION');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  shutdown('UNHANDLED_REJECTION');
});

module.exports = { app, config, server };

