#!/usr/bin/env node
/**
 * Security test script for the Express application
 * Tests common security vulnerabilities
 */

const axios = require('axios');
const https = require('https');

// Use a custom agent that doesn't verify SSL for testing (not for production!)
const agent = new https.Agent({  
  rejectUnauthorized: false
});

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function testSecurity() {
  console.log('🚀 Starting Security Tests...\n');

  const tests = [
    testSecurityHeaders,
    testCorsSecurity,
    testRateLimiting,
    testInformationDisclosure,
    testJsonInjection,
    testMissingAuthentication
  ];

  let passed = 0;
  let failed = 0;

  for (const test of tests) {
    try {
      await test();
      passed++;
    } catch (error) {
      console.error(`❌ ${test.name}: ${error.message}`);
      failed++;
    }
  }

  console.log(`\n📊 Results: ${passed} passed, ${failed} failed`);
  console.log(failed > 0 ? '⚠️  Security issues detected!' : '✅ All security tests passed!');
}

async function testSecurityHeaders() {
  const response = await axios.get(`${BASE_URL}/health`, { httpsAgent: agent });

  const securityHeaders = [
    'x-frame-options',
    'x-content-type-options',
    'x-xss-protection',
    'content-security-policy',
    'strict-transport-security'
  ];

  const missingHeaders = securityHeaders.filter(header => !response.headers[header.toLowerCase()]);

  if (missingHeaders.length > 0) {
    throw new Error(`Missing security headers: ${missingHeaders.join(', ')}`);
  }

  console.log('✅ Security headers test passed');
}

async function testCorsSecurity() {
  // Test from unauthorized origin
  try {
    await axios.get(`${BASE_URL}/health`, {
      headers: {
        'Origin': 'http://malicious-site.com'
      },
      httpsAgent: agent
    });

    // If request succeeds with unauthorized origin, that's a security issue
    const response = await axios.get(`${BASE_URL}/health`, {
      headers: {
        'Origin': 'http://malicious-site.com'
      },
      httpsAgent: agent
    });

    if (response.headers['access-control-allow-origin'] === '*') {
      throw new Error('CORS policy allows all origins (*)');
    }

  } catch (error) {
    // Expected behavior - unauthorized origin should be blocked
    if (error.response && error.response.status === 403) {
      console.log('✅ CORS security test passed');
      return;
    }
    // Re-throw if it's a different error
    if (error.response && error.response.status === 0) {
      // Network error, might be expected
      console.log('✅ CORS likely blocked the request');
      return;
    }
    throw error;
  }
}

async function testRateLimiting() {
  const requests = [];

  // Make multiple requests quickly
  for (let i = 0; i < 150; i++) {
    requests.push(
      axios.get(`${BASE_URL}/health`, { 
        httpsAgent: agent,
        timeout: 1000
      }).catch(() => {})
    );
  }

  await Promise.all(requests);

  // Try one more request
  try {
    await axios.get(`${BASE_URL}/health`, { 
      httpsAgent: agent,
      timeout: 1000 
    });
    console.log('✅ Rate limiting test passed (might need adjustment)');
  } catch (error) {
    if (error.response && error.response.status === 429) {
      console.log('✅ Rate limiting test passed');
    } else {
      throw new Error('Rate limiting not properly configured');
    }
  }
}

async function testInformationDisclosure() {
  // Test error handling
  try {
    await axios.get(`${BASE_URL}/non-existent-route`, { httpsAgent: agent });
  } catch (error) {
    const response = error.response;

    // Check if error response contains stack traces or sensitive info
    const body = JSON.stringify(response.data || {});

    const sensitivePatterns = [
      /at\s.+\(/i, // Stack traces
      /node_modules/i,
      /file:\/\//i,
      /database/i,
      /password/i,
      /secret/i,
      /key/i
    ];

    for (const pattern of sensitivePatterns) {
      if (pattern.test(body)) {
        throw new Error(`Possible information disclosure in error response: ${body.substring(0, 100)}...`);
      }
    }
  }

  console.log('✅ Information disclosure test passed');
}

async function testJsonInjection() {
  // Test with malformed JSON
  try {
    await axios.post(`${BASE_URL}/health`, 'malformed{json}', {
      headers: {
        'Content-Type': 'application/json'
      },
      httpsAgent: agent
    });
  } catch (error) {
    // Should get a 400 or similar error
    if (error.response && error.response.status >= 400 && error.response.status < 500) {
      console.log('✅ JSON injection test passed');
      return;
    }
  }

  console.log('⚠️ JSON injection test inconclusive');
}

async function testMissingAuthentication() {
  // Test if sensitive endpoints are protected
  const sensitiveEndpoints = ['/login', '/admin', '/api/secrets'];

  for (const endpoint of sensitiveEndpoints) {
    try {
      const response = await axios.get(`${BASE_URL}${endpoint}`, { 
        httpsAgent: agent,
        validateStatus: () => true // Don't throw on 404
      });

      if (response.status === 200 && endpoint === '/login') {
        // Login endpoint exists but might be intentional
        console.log('⚠️ Login endpoint is accessible');
      } else if (response.status === 200 && endpoint.includes('admin')) {
        throw new Error(`Admin endpoint ${endpoint} is publicly accessible`);
      }
    } catch (error) {
      // Endpoint might not exist, which is fine
    }
  }

  console.log('✅ Authentication test passed');
}

// Run tests if this script is executed directly
if (require.main === module) {
  testSecurity().catch(console.error);
}

module.exports = {
  testSecurity,
  testSecurityHeaders,
  testCorsSecurity,
  testRateLimiting,
  testInformationDisclosure,
  testJsonInjection,
  testMissingAuthentication
};

