/**
 * Centralized configuration module
 * Loads environment variables and provides configuration objects
 */

const dotenv = require('dotenv');
const path = require('path');

// Determine which .env file to load based on NODE_ENV
const envFile = process.env.NODE_ENV === 'test' 
  ? '.env.test' 
  : process.env.NODE_ENV === 'production'
    ? '.env.production'
    : '.env.development';

// Load environment variables
try {
  dotenv.config({ path: path.resolve(process.cwd(), envFile) });

  // Fallback to .env if specific file doesn't exist
  if (!process.env.PORT && process.env.NODE_ENV) {
    dotenv.config({ path: path.resolve(process.cwd(), '.env') });
  }
} catch (error) {
  console.warn(`Could not load ${envFile}, using default values`);
}

// Parse CSP directives from JSON string
let cspDirectives = {
  defaultSrc: ["'self'"],
  styleSrc: ["'self'", "'unsafe-inline'"],
  scriptSrc: ["'self'"],
  imgSrc: ["'self'", "data:", "https:"]
};

try {
  if (process.env.CSP_DIRECTIVES) {
    const parsedCsp = JSON.parse(process.env.CSP_DIRECTIVES);
    cspDirectives = { ...cspDirectives, ...parsedCsp };
  }
} catch (error) {
  console.warn('Invalid CSP_DIRECTIVES JSON, using defaults');
}

// Configuration object
const config = {
  // Server configuration
  server: {
    port: parseInt(process.env.PORT, 10) || 3000,
    host: process.env.HOST || 'localhost',
    nodeEnv: process.env.NODE_ENV || 'development',
    isProduction: (process.env.NODE_ENV || 'development') === 'production',
    isDevelopment: (process.env.NODE_ENV || 'development') === 'development',
    isTest: (process.env.NODE_ENV || 'development') === 'test'
  },

  // Security configuration
  security: {
    cors: {
      allowedOrigins: process.env.ALLOWED_ORIGINS 
        ? process.env.ALLOWED_ORIGINS.split(',').map(origin => origin.trim())
        : ['http://localhost:3000'],
      credentials: process.env.CORS_CREDENTIALS === 'true' || true,
      optionsSuccessStatus: parseInt(process.env.CORS_OPTIONS_SUCCESS_STATUS, 10) || 200
    },

    rateLimiting: {
      api: {
        windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 15 * 60 * 1000, // 15 minutes
        max: parseInt(process.env.RATE_LIMIT_MAX, 10) || 100,
        message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later',
        standardHeaders: process.env.RATE_LIMIT_STANDARD_HEADERS === 'true' || true,
        legacyHeaders: process.env.RATE_LIMIT_LEGACY_HEADERS === 'false' || false
      },
      auth: {
        windowMs: parseInt(process.env.AUTH_RATE_LIMIT_WINDOW_MS, 10) || 60 * 60 * 1000, // 1 hour
        max: parseInt(process.env.AUTH_RATE_LIMIT_MAX, 10) || 5,
        message: process.env.AUTH_RATE_LIMIT_MESSAGE || 'Too many login attempts from this IP, please try again after an hour'
      }
    },

    requestLimits: {
      json: process.env.JSON_BODY_LIMIT || '1mb',
      urlencoded: process.env.URLENCODED_BODY_LIMIT || '1mb',
      parameterLimit: parseInt(process.env.PARAMETER_LIMIT, 10) || 10
    },

    helmet: {
      contentSecurityPolicy: {
        directives: cspDirectives
      },
      hsts: {
        maxAge: parseInt(process.env.HSTS_MAX_AGE, 10) || 31536000,
        includeSubDomains: process.env.HSTS_INCLUDE_SUBDOMAINS === 'true' || true,
        preload: process.env.HSTS_PRELOAD === 'true' || true
      },
      referrerPolicy: { 
        policy: process.env.REFERRER_POLICY || 'strict-origin-when-cross-origin' 
      }
    },

    logging: {
      sanitizeHeaders: (process.env.LOGGING_SANITIZE_HEADERS || 'authorization,cookie,x-api-key')
        .split(',')
        .map(header => header.trim()),
      logRequests: process.env.LOGGING_REQUESTS === 'true' || true,
      logErrors: process.env.LOGGING_ERRORS === 'true' || true
    }
  },

  // Test configuration (only for testing environment)
  test: {
    baseUrl: process.env.TEST_BASE_URL || 'http://localhost:3000',
    securityTest: {
      rateLimitRequests: parseInt(process.env.TEST_RATE_LIMIT_REQUESTS, 10) || 150,
      timeout: parseInt(process.env.TEST_TIMEOUT, 10) || 1000,
      maliciousOrigin: process.env.TEST_MALICIOUS_ORIGIN || 'http://malicious-site.com',
      sensitiveEndpoints: (process.env.TEST_SENSITIVE_ENDPOINTS || '/login,/admin,/api/secrets')
        .split(',')
        .map(endpoint => endpoint.trim())
    }
  },

  // Application-specific configuration
  app: {
    usersEndpointLimit: parseInt(process.env.USERS_ENDPOINT_LIMIT, 10) || 100,
    cacheControl: {
      noCachePaths: (process.env.NO_CACHE_PATHS || '/login,/auth')
        .split(',')
        .map(path => path.trim())
    }
  }
};

// Validation
if (config.security.rateLimiting.api.max < 1) {
  console.warn('RATE_LIMIT_MAX should be at least 1, using default value');
  config.security.rateLimiting.api.max = 100;
}

if (config.security.rateLimiting.auth.max < 1) {
  console.warn('AUTH_RATE_LIMIT_MAX should be at least 1, using default value');
  config.security.rateLimiting.auth.max = 5;
}

if (config.security.requestLimits.parameterLimit < 1) {
  console.warn('PARAMETER_LIMIT should be at least 1, using default value');
  config.security.requestLimits.parameterLimit = 10;
}

// Export configuration
module.exports = config;

// Log configuration in development mode (without exposing secrets)
if (config.server.isDevelopment) {
  console.log('Configuration loaded:', {
    server: {
      port: config.server.port,
      host: config.server.host,
      nodeEnv: config.server.nodeEnv
    },
    security: {
      cors: {
        allowedOrigins: config.security.cors.allowedOrigins
      },
      rateLimiting: {
        api: {
          windowMs: config.security.rateLimiting.api.windowMs,
          max: config.security.rateLimiting.api.max
        }
      }
    }
  });
}

/**
 * Express application with fully externalized configuration
 * All hardcoded values have been moved to environment variables
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// Load centralized configuration
const config = require('./config');

const app = express();

// Security middleware with configurable settings
app.use(helmet(config.security.helmet));

// CORS configuration using environment variables
app.use(cors({
  origin: function (origin, callback) {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (config.security.cors.allowedOrigins.indexOf(origin) === -1) {
      const msg = `The CORS policy for this site does not allow access from ${origin}`;
      return callback(new Error(msg), false);
    }
    return callback(null, true);
  },
  credentials: config.security.cors.credentials,
  optionsSuccessStatus: config.security.cors.optionsSuccessStatus
}));

// Rate limiting with configurable values
const apiLimiter = rateLimit({
  windowMs: config.security.rateLimiting.api.windowMs,
  max: config.security.rateLimiting.api.max,
  message: config.security.rateLimiting.api.message,
  standardHeaders: config.security.rateLimiting.api.standardHeaders,
  legacyHeaders: config.security.rateLimiting.api.legacyHeaders
});

const authLimiter = rateLimit({
  windowMs: config.security.rateLimiting.auth.windowMs,
  max: config.security.rateLimiting.auth.max,
  message: config.security.rateLimiting.auth.message
});

// Apply rate limiting to appropriate routes
app.use('/api/', apiLimiter);

// Body parsing with configurable limits
app.use(express.json({ 
  limit: config.security.requestLimits.json,
  verify: (req, res, buf) => {
    // Additional JSON validation
    try {
      JSON.parse(buf.toString());
    } catch (e) {
      throw new Error('Invalid JSON');
    }
  }
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: config.security.requestLimits.urlencoded,
  parameterLimit: config.security.requestLimits.parameterLimit
}));

// Request logging middleware (configurable)
if (config.security.logging.logRequests) {
  app.use((req, res, next) => {
    const start = Date.now();

    // Sanitize sensitive headers before logging
    const sanitizedHeaders = { ...req.headers };
    config.security.logging.sanitizeHeaders.forEach(header => {
      if (sanitizedHeaders[header]) {
        sanitizedHeaders[header] = '[REDACTED]';
      }
    });

    // Log the request
    console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`, {
      ip: req.ip,
      userAgent: req.get('user-agent'),
      headers: sanitizedHeaders
    });

    res.on('finish', () => {
      const duration = Date.now() - start;
      console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
    });

    next();
  });
}

// Security headers nonce generation
app.use((req, res, next) => {
  // Add nonce for CSP if needed
  res.locals.cspNonce = Buffer.from(Math.random().toString()).toString('base64').slice(0, 16);
  next();
});

// Routes
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.server.nodeEnv,
    port: config.server.port,
    configSource: 'environment-variables'
  });
});

app.get('/users', (req, res) => {
  // Input validation with configurable limit
  const { limit } = req.query;
  const maxLimit = config.app.usersEndpointLimit;

  if (limit && (isNaN(limit) || parseInt(limit, 10) > maxLimit || parseInt(limit, 10) < 1)) {
    return res.status(400).json({ 
      error: `Invalid limit parameter. Must be between 1 and ${maxLimit}` 
    });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Authentication endpoint with stricter rate limiting
app.post('/login', authLimiter, (req, res) => {
  // TODO: Implement proper authentication
  res.json({ 
    message: 'Login endpoint - authentication not implemented',
    rateLimit: `${config.security.rateLimiting.auth.max} attempts per hour`
  });
});

// Error handling middleware with configurable logging
if (config.security.logging.logErrors) {
  app.use((err, req, res, next) => {
    console.error('[ERROR]', {
      message: err.message,
      stack: config.server.isProduction ? undefined : err.stack,
      path: req.path,
      method: req.method,
      ip: req.ip
    });

    // Don't leak error details in production
    const response = config.server.isProduction
      ? { error: 'Internal server error' }
      : { 
          error: err.message,
          ...(config.server.isDevelopment && { stack: err.stack })
        };

    res.status(err.status || 500).json(response);
  });
}

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path,
    method: req.method
  });
});

// Cache control for sensitive endpoints
app.use((req, res, next) => {
  // Prevent browsers from caching sensitive data
  if (config.app.cacheControl.noCachePaths.some(path => req.path.includes(path))) {
    res.set('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.set('Pragma', 'no-cache');
    res.set('Expires', '0');
    res.set('Surrogate-Control', 'no-store');
  }
  next();
});

// Start server with configurable host and port
app.listen(config.server.port, config.server.host, () => {
  console.log(`
🚀 Server Information:
  - URL: http://${config.server.host}:${config.server.port}
  - Environment: ${config.server.nodeEnv}
  - Port: ${config.server.port}
  - Host: ${config.server.host}
  `);

  console.log(`
🔒 Security Configuration:
  - CORS Origins: ${config.security.cors.allowedOrigins.join(', ')}
  - Rate Limit: ${config.security.rateLimiting.api.max} requests per ${config.security.rateLimiting.api.windowMs / 60000} minutes
  - Auth Rate Limit: ${config.security.rateLimiting.auth.max} attempts per hour
  - Body Limit: ${config.security.requestLimits.json}
  `);

  // Security warnings for production
  if (config.server.isProduction) {
    console.warn('\n⚠️  PRODUCTION MODE - SECURITY WARNINGS:');

    if (config.security.cors.allowedOrigins.length === 1 && 
        config.security.cors.allowedOrigins[0].includes('localhost')) {
      console.warn('  ⚠️  CORS is configured for localhost only!');
    }

    if (config.security.rateLimiting.api.max > 500) {
      console.warn('  ⚠️  Rate limit is very high for production!');
    }

    if (config.security.requestLimits.json > '10mb') {
      console.warn('  ⚠️  Body size limit is very large for production!');
    }
  }
});

module.exports = app;

#!/usr/bin/env node
/**
 * Security test script for the Express application
 * Uses centralized configuration for all test parameters
 */

const axios = require('axios');
const https = require('https');

// Load configuration
const config = require('./config');

// Use a custom agent that doesn't verify SSL for testing (not for production!)
const agent = new https.Agent({  
  rejectUnauthorized: false
});

const BASE_URL = config.test.baseUrl;

async function testSecurity() {
  console.log('🚀 Starting Security Tests...\n');
  console.log(`Test Configuration:`);
  console.log(`  Base URL: ${BASE_URL}`);
  console.log(`  Environment: ${config.server.nodeEnv}`);
  console.log(`  Rate Limit Test Requests: ${config.test.securityTest.rateLimitRequests}`);
  console.log(`  Timeout: ${config.test.securityTest.timeout}ms\n`);

  const tests = [
    testSecurityHeaders,
    testCorsSecurity,
    testRateLimiting,
    testInformationDisclosure,
    testJsonInjection,
    testMissingAuthentication
  ];

  let passed = 0;
  let failed = 0;
  let warnings = 0;

  for (const test of tests) {
    try {
      const result = await test();
      if (result === 'warning') {
        warnings++;
      } else {
        passed++;
      }
    } catch (error) {
      console.error(`❌ ${test.name}: ${error.message}`);
      failed++;
    }
  }

  console.log(`\n📊 Test Results:`);
  console.log(`  ✅ Passed: ${passed}`);
  console.log(`  ⚠️  Warnings: ${warnings}`);
  console.log(`  ❌ Failed: ${failed}`);

  if (failed > 0) {
    console.log('\n🔴 SECURITY ISSUES DETECTED!');
  } else if (warnings > 0) {
    console.log('\n🟡 SECURITY WARNINGS - Review recommended');
  } else {
    console.log('\n🟢 ALL SECURITY TESTS PASSED!');
  }

  // Configuration audit
  console.log('\n🔧 Configuration Audit:');
  auditConfiguration();
}

async function testSecurityHeaders() {
  const response = await axios.get(`${BASE_URL}/health`, { httpsAgent: agent });

  const securityHeaders = [
    'x-frame-options',
    'x-content-type-options',
    'x-xss-protection',
    'content-security-policy',
    'strict-transport-security'
  ];

  const missingHeaders = securityHeaders.filter(header => !response.headers[header.toLowerCase()]);

  if (missingHeaders.length > 0) {
    throw new Error(`Missing security headers: ${missingHeaders.join(', ')}`);
  }

  console.log('✅ Security headers test passed');
}

async function testCorsSecurity() {
  // Test from unauthorized origin
  try {
    await axios.get(`${BASE_URL}/health`, {
      headers: {
        'Origin': config.test.securityTest.maliciousOrigin
      },
      httpsAgent: agent
    });

    // If request succeeds with unauthorized origin, that's a security issue
    const response = await axios.get(`${BASE_URL}/health`, {
      headers: {
        'Origin': config.test.securityTest.maliciousOrigin
      },
      httpsAgent: agent
    });

    if (response.headers['access-control-allow-origin'] === '*') {
      throw new Error('CORS policy allows all origins (*)');
    }

  } catch (error) {
    // Expected behavior - unauthorized origin should be blocked
    if (error.response && error.response.status === 403) {
      console.log('✅ CORS security test passed');
      return;
    }
    // Network error, might be expected
    if (error.response && error.response.status === 0) {
      console.log('✅ CORS likely blocked the request');
      return;
    }
    throw error;
  }
}

async function testRateLimiting() {
  const requests = [];
  const testRequests = config.test.securityTest.rateLimitRequests;
  const timeout = config.test.securityTest.timeout;

  // Make multiple requests quickly
  for (let i = 0; i < testRequests; i++) {
    requests.push(
      axios.get(`${BASE_URL}/health`, { 
        httpsAgent: agent,
        timeout: timeout
      }).catch(() => {})
    );
  }

  await Promise.all(requests);

  // Try one more request
  try {
    await axios.get(`${BASE_URL}/health`, { 
      httpsAgent: agent,
      timeout: timeout 
    });
    console.log('✅ Rate limiting test passed (might need adjustment)');
  } catch (error) {
    if (error.response && error.response.status === 429) {
      console.log('✅ Rate limiting test passed');
    } else {
      throw new Error('Rate limiting not properly configured');
    }
  }
}

async function testInformationDisclosure() {
  // Test error handling
  try {
    await axios.get(`${BASE_URL}/non-existent-route`, { httpsAgent: agent });
  } catch (error) {
    const response = error.response;

    // Check if error response contains stack traces or sensitive info
    const body = JSON.stringify(response.data || {});

    const sensitivePatterns = [
      /at\s.+\(/i, // Stack traces
      /node_modules/i,
      /file:\/\//i,
      /database/i,
      /password/i,
      /secret/i,
      /key/i,
      /token/i,
      /CANARY/i  // Detect test secrets
    ];

    for (const pattern of sensitivePatterns) {
      if (pattern.test(body)) {
        throw new Error(`Possible information disclosure in error response: ${body.substring(0, 100)}...`);
      }
    }
  }

  console.log('✅ Information disclosure test passed');
}

async function testJsonInjection() {
  // Test with malformed JSON
  try {
    await axios.post(`${BASE_URL}/health`, 'malformed{json}', {
      headers: {
        'Content-Type': 'application/json'
      },
      httpsAgent: agent
    });
  } catch (error) {
    // Should get a 400 or similar error
    if (error.response && error.response.status >= 400 && error.response.status < 500) {
      console.log('✅ JSON injection test passed');
      return;
    }
  }

  console.log('⚠️ JSON injection test inconclusive');
  return 'warning';
}

async function testMissingAuthentication() {
  let warnings = 0;

  // Test if sensitive endpoints are protected
  for (const endpoint of config.test.securityTest.sensitiveEndpoints) {
    try {
      const response = await axios.get(`${BASE_URL}${endpoint}`, { 
        httpsAgent: agent,
        validateStatus: () => true // Don't throw on 404
      });

      if (response.status === 200 && endpoint === '/login') {
        console.log('⚠️ Login endpoint is publicly accessible');
        warnings++;
      } else if (response.status === 200 && endpoint.includes('admin')) {
        throw new Error(`Admin endpoint ${endpoint} is publicly accessible`);
      }
    } catch (error) {
      // Endpoint might not exist, which is fine
    }
  }

  if (warnings === 0) {
    console.log('✅ Authentication test passed');
  } else {
    return 'warning';
  }
}

function auditConfiguration() {
  console.log('  Security Configuration:');

  // CORS audit
  if (config.security.cors.allowedOrigins.includes('*')) {
    console.log('  ❌ CORS allows all origins (*) - SECURITY RISK');
  } else if (config.server.isProduction && 
             config.security.cors.allowedOrigins.some(origin => origin.includes('localhost'))) {
    console.log('  ⚠️  Production CORS includes localhost - might be incorrect');
  } else {
    console.log(`  ✅ CORS configured for ${config.security.cors.allowedOrigins.length} origins`);
  }

  // Rate limiting audit
  console.log(`  ✅ Rate limit: ${config.security.rateLimiting.api.max} requests per ${config.security.rateLimiting.api.windowMs / 60000} minutes`);

  if (config.server.isProduction && config.security.rateLimiting.api.max > 500) {
    console.log('  ⚠️  Production rate limit is very high - consider lowering');
  }

  // Request limits audit
  console.log(`  ✅ Body size limit: ${config.security.requestLimits.json}`);

  // Environment-specific checks
  if (config.server.isProduction) {
    console.log('  🔒 Production environment detected');

    // Check for default/placeholder values in production
    const placeholderPatterns = [
      /yourdomain\.com/i,
      /example\.com/i,
      /localhost/i,
      /CANARY/i,
      /test/i,
      /dev/i
    ];

    const configString = JSON.stringify(config);
    for (const pattern of placeholderPatterns) {
      if (pattern.test(configString)) {
        console.log('  ⚠️  Placeholder values detected in production configuration');
        break;
      }
    }
  }

  console.log(`  📊 Request logging: ${config.security.logging.logRequests ? 'enabled' : 'disabled'}`);
  console.log(`  📊 Error logging: ${config.security.logging.logErrors ? 'enabled' : 'disabled'}`);
}

// Run tests if this script is executed directly
if (require.main === module) {
  testSecurity().catch(console.error);
}

module.exports = {
  testSecurity,
  testSecurityHeaders,
  testCorsSecurity,
  testRateLimiting,
  testInformationDisclosure,
  testJsonInjection,
  testMissingAuthentication,
  auditConfiguration
};

