// CRITICAL SECURITY FIXES FOR app.js
// These are the most urgent security fixes needed

const express = require('express');
const helmet = require('helmet'); // Install with: npm install helmet
const rateLimit = require('express-rate-limit'); // Install with: npm install express-rate-limit
const { validationResult, body } = require('express-validator'); // Install with: npm install express-validator

// Load environment variables
require('dotenv').config(); // Install with: npm install dotenv

const app = express();

// 1. SECURITY HEADERS - Prevents many common attacks
app.use(helmet());

// 2. RATE LIMITING - Prevents brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 3. CORS CONFIGURATION - Control which origins can access your API
const cors = require('cors'); // Install with: npm install cors
const allowedOrigins = process.env.ALLOWED_ORIGINS
  ? process.env.ALLOWED_ORIGINS.split(',')
  : ['http://localhost:3000', 'http://localhost:8080'];

app.use(cors({
  origin: function(origin, callback) {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (allowedOrigins.indexOf(origin) === -1) {
      const msg = 'The CORS policy for this site does not allow access from the specified origin.';
      return callback(new Error(msg), false);
    }
    return callback(null, true);
  },
  credentials: true,
}));

// 4. INPUT VALIDATION MIDDLEWARE
const sanitizeInput = (req, res, next) => {
  // Basic sanitization - prevent XSS attacks
  for (const key in req.query) {
    if (typeof req.query[key] === 'string') {
      req.query[key] = req.query[key].replace(/[<>]/g, '');
    }
  }
  for (const key in req.body) {
    if (typeof req.body[key] === 'string') {
      req.body[key] = req.body[key].replace(/[<>]/g, '');
    }
  }
  next();
};

app.use(sanitizeInput);

// 5. BASIC LOGGING MIDDLEWARE
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url} - ${req.ip}`);
  next();
});

// 6. HEALTH CHECK ENDPOINT (with validation)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// 7. USERS ENDPOINT (with authentication check - placeholder)
// TODO: Implement proper authentication
const requireAuth = (req, res, next) => {
  // This is a placeholder - implement proper JWT/API key validation
  const apiKey = req.headers['x-api-key'] || req.query.api_key;

  if (!apiKey) {
    return res.status(401).json({ 
      error: 'Authentication required',
      message: 'Please provide an API key in x-api-key header or api_key query parameter'
    });
  }

  // In production, validate against database or token store
  if (apiKey !== process.env.API_KEY) {
    return res.status(403).json({ 
      error: 'Invalid API key',
      message: 'The provided API key is not valid'
    });
  }

  next();
};

// 8. PROTECTED USERS ENDPOINT
app.get('/users', requireAuth, [
  // Input validation
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Return sanitized user data (never passwords or sensitive info)
  res.json([
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      role: 'user',
      createdAt: '2023-01-01'
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      role: 'user',
      createdAt: '2023-01-02'
    },
  ]);
});

// 9. ERROR HANDLING MIDDLEWARE
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose stack traces in production
  const isProduction = process.env.NODE_ENV === 'production';
  const errorResponse = {
    error: isProduction ? 'Internal Server Error' : err.message,
    message: 'Something went wrong'
  };

  if (!isProduction) {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// 10. 404 HANDLER
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
