// Application with all hardcoded values replaced by environment variables
// This is a secure version that uses configuration from environment

const express = require('express');
// Load environment variables from .env file
require('dotenv').config();

const app = express();

// ============================================================================
// CONFIGURATION FROM ENVIRONMENT VARIABLES
// ============================================================================

// Server Configuration
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';
const NODE_ENV = process.env.NODE_ENV || 'development';

// Security Configuration
const API_KEY = process.env.API_KEY;
const JWT_SECRET = process.env.JWT_SECRET;
const SESSION_SECRET = process.env.SESSION_SECRET;

// Database Configuration
const DB_CONFIG = {
  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME || 'myapp',
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  // Connection pool settings
  max: process.env.DB_POOL_MAX || 10,
  idleTimeoutMillis: process.env.DB_POOL_IDLE_TIMEOUT || 30000,
};

// External Services Configuration
const EXTERNAL_SERVICES = {
  stripe: {
    secretKey: process.env.STRIPE_SECRET_KEY,
    publishableKey: process.env.STRIPE_PUBLISHABLE_KEY,
  },
  email: {
    service: process.env.EMAIL_SERVICE || 'gmail',
    user: process.env.EMAIL_USER,
    password: process.env.EMAIL_PASSWORD,
    from: process.env.EMAIL_FROM || 'noreply@example.com',
  },
};

// Application Configuration
const APP_CONFIG = {
  rateLimit: {
    windowMs: process.env.RATE_LIMIT_WINDOW_MS || 15 * 60 * 1000, // 15 minutes
    max: process.env.RATE_LIMIT_MAX || 100,
  },
  cors: {
    allowedOrigins: process.env.ALLOWED_ORIGINS 
      ? process.env.ALLOWED_ORIGINS.split(',') 
      : ['http://localhost:3000', 'http://localhost:8080'],
  },
  // You could load user data from environment variables or external config
  // For example: process.env.DEFAULT_USERS could be a JSON string
  defaultUsers: [
    { 
      id: 1, 
      name: process.env.DEFAULT_USER1_NAME || 'Alice', 
      email: process.env.DEFAULT_USER1_EMAIL || 'alice@example.com' 
    },
    { 
      id: 2, 
      name: process.env.DEFAULT_USER2_NAME || 'Bob', 
      email: process.env.DEFAULT_USER2_EMAIL || 'bob@example.com' 
    },
  ],
};

// ============================================================================
// VALIDATE REQUIRED CONFIGURATION
// ============================================================================

function validateConfiguration() {
  const errors = [];

  // Validate required environment variables for production
  if (NODE_ENV === 'production') {
    const required = ['API_KEY', 'DB_USER', 'DB_PASSWORD'];
    required.forEach(key => {
      if (!process.env[key]) {
        errors.push(`Missing required environment variable: ${key}`);
      }
    });

    // Warn about using defaults in production
    if (PORT === 3000) {
      console.warn('⚠️  Warning: Using default port 3000 in production');
    }

    if (DB_CONFIG.host === 'localhost') {
      console.warn('⚠️  Warning: Using localhost database in production');
    }
  }

  if (errors.length > 0) {
    console.error('Configuration errors:');
    errors.forEach(error => console.error(`  - ${error}`));
    console.error('\nPlease check your .env file and environment variables.');
    process.exit(1);
  }
}

// Call validation
validateConfiguration();

// ============================================================================
// MIDDLEWARE SETUP
// ============================================================================

// Basic logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} [${NODE_ENV}] ${req.method} ${req.url} - ${req.ip}`);
  next();
});

// ============================================================================
// ROUTES WITH CONFIGURABLE VALUES
// ============================================================================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    server: `${HOST}:${PORT}`,
    // Don't expose sensitive config in health check
  });
});

// Configuration endpoint (protected or development only)
app.get('/config-info', (req, res) => {
  // Only show in development or with proper auth
  if (NODE_ENV !== 'development') {
    return res.status(403).json({ error: 'Configuration endpoint not available' });
  }

  // Return safe configuration info
  res.json({
    environment: NODE_ENV,
    server: {
      port: PORT,
      host: HOST,
    },
    database: {
      host: DB_CONFIG.host,
      port: DB_CONFIG.port,
      database: DB_CONFIG.database,
      // Don't expose credentials
      hasCredentials: !!(DB_CONFIG.user && DB_CONFIG.password),
    },
    security: {
      hasApiKey: !!API_KEY,
      hasJwtSecret: !!JWT_SECRET,
    },
    rateLimit: APP_CONFIG.rateLimit,
    cors: {
      allowedOriginsCount: APP_CONFIG.cors.allowedOrigins.length,
    },
  });
});

// Users endpoint - now using configurable user data
app.get('/users', (req, res) => {
  // In a real application, this would come from a database
  // For now, we use the configurable default users
  res.json(APP_CONFIG.defaultUsers);
});

// ============================================================================
// START SERVER WITH CONFIGURABLE SETTINGS
// ============================================================================

app.listen(PORT, HOST, () => {
  console.log(`=========================================`);
  console.log(`🚀 Server started successfully!`);
  console.log(`=========================================`);
  console.log(`Environment: ${NODE_ENV}`);
  console.log(`Server: http://${HOST === '0.0.0.0' ? 'localhost' : HOST}:${PORT}`);
  console.log(`Port: ${PORT}`);
  console.log(`Database: ${DB_CONFIG.host}:${DB_CONFIG.port}/${DB_CONFIG.database}`);
  console.log(`Rate Limit: ${APP_CONFIG.rateLimit.max} req/${APP_CONFIG.rateLimit.windowMs/60000}min`);
  console.log(`CORS Allowed Origins: ${APP_CONFIG.cors.allowedOrigins.length}`);
  console.log(`=========================================`);

  // Development mode warnings
  if (NODE_ENV === 'development') {
    console.log('\n⚠️  DEVELOPMENT MODE WARNINGS:');
    console.log('   - Using default/fallback configuration values');
    console.log('   - /config-info endpoint is accessible');
    console.log('   - Consider setting up a proper .env file');
  }

  // Security checklist
  console.log('\n🔒 SECURITY CHECKLIST:');
  console.log(`   ${API_KEY ? '✅' : '❌'} API_KEY is ${API_KEY ? 'set' : 'NOT set'}`);
  console.log(`   ${DB_CONFIG.user ? '✅' : '❌'} Database user is ${DB_CONFIG.user ? 'set' : 'NOT set'}`);
  console.log(`   ${DB_CONFIG.password ? '✅' : '❌'} Database password is ${DB_CONFIG.password ? 'set' : 'NOT set'}`);

  if (NODE_ENV === 'production') {
    if (!API_KEY || !DB_CONFIG.user || !DB_CONFIG.password) {
      console.log('\n⚠️  WARNING: Missing required configuration for production!');
    }
  }
});

module.exports = {
  app,
  config: {
    server: { PORT, HOST, NODE_ENV },
    database: DB_CONFIG,
    security: { API_KEY, JWT_SECRET, SESSION_SECRET },
    app: APP_CONFIG,
    external: EXTERNAL_SERVICES,
  },
};

// ============================================================================
// .ENV FILE TEMPLATE
// ============================================================================
/*
# Copy this to .env file and fill in your values

# Server Configuration
PORT=3000
HOST=0.0.0.0
NODE_ENV=development

# Security
API_KEY=your_secure_api_key_here
JWT_SECRET=your_jwt_secret_key_here
