// Secured version of app.js with security fixes
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Security headers (CRITICAL)
app.use(helmet());

// 2. Rate limiting (CRITICAL)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// 3. CORS configuration (HIGH)
const allowedOrigins = process.env.ALLOWED_ORIGINS ? 
  process.env.ALLOWED_ORIGINS.split(',') : 
  ['http://localhost:3000', 'http://localhost:3001'];

app.use(cors({
  origin: function(origin, callback) {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (allowedOrigins.indexOf(origin) === -1) {
      const msg = 'The CORS policy for this site does not allow access from the specified Origin.';
      return callback(new Error(msg), false);
    }
    return callback(null, true);
  },
  credentials: true,
  optionsSuccessStatus: 200
}));

// 4. Request parsing with size limits (MEDIUM)
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: true }));

// 5. Logging (MEDIUM)
app.use(morgan('combined'));

// ========== VALIDATION MIDDLEWARE ==========

const validateHealthRequest = [
  // Add any specific validation for health endpoint if needed
];

const validateUsersRequest = [
  // Add validation for query parameters if users endpoint accepts them
  body('page').optional().isInt({ min: 1 }),
  body('limit').optional().isInt({ min: 1, max: 100 }),
];

// ========== ROUTES WITH VALIDATION ==========

app.get('/health', validateHealthRequest, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

app.get('/users', validateUsersRequest, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Simulated user data - in production, this would come from a database
  // with proper parameterized queries to prevent SQL injection
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      // Never expose sensitive data like passwords in responses
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com' 
    },
  ];

  // Always sanitize output data
  const sanitizedUsers = users.map(user => ({
    id: user.id,
    name: user.name,
    email: user.email
    // Exclude sensitive fields
  }));

  res.json(sanitizedUsers);
});

// ========== ERROR HANDLING MIDDLEWARE ==========

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${new Date().toISOString()}:`, err);

  // Don't expose stack traces in production
  const errorResponse = {
    error: 'Internal Server Error',
    message: 'An unexpected error occurred'
  };

  // Include more details in development
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.details = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// ========== SERVER CONFIGURATION ==========

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Security: Don't expose server information in headers
app.disable('x-powered-by');

const server = app.listen(PORT, HOST, () => {
  console.log(`Secure server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Allowed origins: ${allowedOrigins.join(', ')}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = { app, server };

// ========== ADDITIONAL SECURITY RECOMMENDATIONS ==========
/*
  To further secure this application:

  1. Authentication/Authorization:
     - Implement JWT or session-based authentication
     - Add role-based access control (RBAC)

  2. Database Security:
     - Use parameterized queries to prevent SQL injection
     - Implement connection pooling with limits
     - Use environment variables for database credentials

  3. API Security:
     - Implement API key authentication for public endpoints
     - Add request signing for sensitive operations
     - Implement request/response encryption

  4. Monitoring:
     - Set up security event logging
     - Implement intrusion detection
     - Regular security scanning

  5. Environment:
     - Use different configuration for dev/staging/prod
     - Rotate secrets regularly
     - Implement secret management (AWS Secrets Manager, HashiCorp Vault)

  6. Dependencies:
     - Regularly run `npm audit` and `npm outdated`
     - Use dependency locking (package-lock.json)
     - Consider using Snyk or similar vulnerability scanners
*/

