// Configuration module that loads and validates environment variables
require('dotenv').config();

const config = {
  // Server Configuration
  server: {
    port: parseInt(process.env.PORT) || 3000,
    host: process.env.HOST || '0.0.0.0',
    environment: process.env.NODE_ENV || 'development',
    isProduction: process.env.NODE_ENV === 'production',
    isDevelopment: process.env.NODE_ENV === 'development',
    isTest: process.env.NODE_ENV === 'test',
  },

  // Security Configuration
  security: {
    rateLimit: {
      windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes
      maxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
      enabled: process.env.ENABLE_RATE_LIMITING !== 'false', // enabled by default
    },
    cors: {
      allowedOrigins: process.env.ALLOWED_ORIGINS 
        ? process.env.ALLOWED_ORIGINS.split(',') 
        : ['http://localhost:3000', 'http://localhost:3001'],
      enabled: process.env.ENABLE_CORS !== 'false', // enabled by default
    },
    request: {
      bodyLimit: process.env.REQUEST_BODY_LIMIT || '1mb',
    },
  },

  // Timeout Configuration
  timeouts: {
    request: parseInt(process.env.REQUEST_TIMEOUT) || 30000, // 30 seconds
    keepAlive: parseInt(process.env.KEEP_ALIVE_TIMEOUT) || 5000, // 5 seconds
    session: parseInt(process.env.SESSION_TIMEOUT) || 86400000, // 24 hours
  },

  // Logging Configuration
  logging: {
    level: process.env.LOG_LEVEL || 'combined',
    directory: process.env.LOG_DIR || './logs',
    maxFiles: parseInt(process.env.LOG_MAX_FILES) || 10,
    maxSize: parseInt(process.env.LOG_MAX_SIZE) || 10485760, // 10MB
    enabled: process.env.ENABLE_LOGGING !== 'false', // enabled by default
  },

  // Feature Flags
  features: {
    debugMode: process.env.DEBUG_MODE === 'true',
    enableRateLimiting: process.env.ENABLE_RATE_LIMITING !== 'false',
    enableCors: process.env.ENABLE_CORS !== 'false',
    enableLogging: process.env.ENABLE_LOGGING !== 'false',
  },

  // Application Configuration
  app: {
    name: process.env.APP_NAME || 'Express Application',
    version: process.env.API_VERSION || 'v1',
    defaultPageSize: parseInt(process.env.DEFAULT_PAGE_SIZE) || 20,
    maxPageSize: parseInt(process.env.MAX_PAGE_SIZE) || 100,
  },
};

// Validation function to ensure required environment variables are set
function validateConfig() {
  const errors = [];

  // Validate server configuration
  if (!config.server.port || config.server.port < 1 || config.server.port > 65535) {
    errors.push('PORT must be between 1 and 65535');
  }

  if (!['development', 'production', 'test'].includes(config.server.environment)) {
    errors.push('NODE_ENV must be one of: development, production, test');
  }

  // Validate rate limiting
  if (config.security.rateLimit.windowMs < 1000) { // Less than 1 second
    errors.push('RATE_LIMIT_WINDOW_MS must be at least 1000ms (1 second)');
  }

  if (config.security.rateLimit.maxRequests < 1) {
    errors.push('RATE_LIMIT_MAX_REQUESTS must be at least 1');
  }

  // Validate request body limit format (e.g., '1mb', '10kb')
  const bodyLimitRegex = /^\d+(?:\.\d+)?(?:b|kb|mb|gb)$/i;
  if (!bodyLimitRegex.test(config.security.request.bodyLimit)) {
    errors.push('REQUEST_BODY_LIMIT must be in format like: 1mb, 10kb, 500b');
  }

  // Validate timeouts
  if (config.timeouts.request < 1000) {
    errors.push('REQUEST_TIMEOUT must be at least 1000ms (1 second)');
  }

  // Return validation result
  if (errors.length > 0) {
    console.error('Configuration validation failed:');
    errors.forEach(error => console.error(`  - ${error}`));
    return false;
  }

  return true;
}

// Helper function to get configuration for current environment
function getConfig() {
  return {
    ...config,
    // Add computed properties
    computed: {
      isSecure: config.server.environment === 'production',
      shouldCompress: config.server.environment === 'production',
      showErrors: config.server.environment !== 'production',
    },
  };
}

// Export configuration
module.exports = {
  config: getConfig(),
  validateConfig,
  // Individual exports for convenience
  server: config.server,
  security: config.security,
  timeouts: config.timeouts,
  logging: config.logging,
  features: config.features,
  app: config.app,
};

// Express application with all configuration from environment variables
const express = require('express');
const { config, validateConfig } = require('./config');

// Validate configuration before starting
if (!validateConfig()) {
  console.error('Invalid configuration. Exiting...');
  process.exit(1);
}

const app = express();

// ========== IMPORT SECURITY MODULES ==========
// Note: These should be added to package.json dependencies
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

// ========== SECURITY MIDDLEWARE (CONFIGURABLE) ==========

// 1. Security headers - always enabled
app.use(helmet());

// 2. Rate limiting - configurable via ENABLE_RATE_LIMITING
if (config.features.enableRateLimiting) {
  const limiter = rateLimit({
    windowMs: config.security.rateLimit.windowMs,
    max: config.security.rateLimit.maxRequests,
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
  });
  app.use(limiter);
  console.log(`Rate limiting enabled: ${config.security.rateLimit.maxRequests} requests per ${config.security.rateLimit.windowMs/60000} minutes`);
}

// 3. CORS - configurable via ENABLE_CORS
if (config.features.enableCors) {
  app.use(cors({
    origin: function(origin, callback) {
      // Allow requests with no origin (like mobile apps or curl requests)
      if (!origin) return callback(null, true);

      if (config.security.cors.allowedOrigins.indexOf(origin) === -1) {
        const msg = `The CORS policy for this site does not allow access from ${origin}. Allowed origins: ${config.security.cors.allowedOrigins.join(', ')}`;
        return callback(new Error(msg), false);
      }
      return callback(null, true);
    },
    credentials: true,
    optionsSuccessStatus: 200,
    maxAge: 86400, // 24 hours
  }));
  console.log(`CORS enabled. Allowed origins: ${config.security.cors.allowedOrigins.join(', ')}`);
}

// 4. Request parsing with configurable limits
app.use(express.json({ limit: config.security.request.bodyLimit }));
app.use(express.urlencoded({ 
  limit: config.security.request.bodyLimit, 
  extended: true 
}));

// 5. Logging - configurable via ENABLE_LOGGING
if (config.features.enableLogging) {
  // Ensure log directory exists
  if (!fs.existsSync(config.logging.directory)) {
    fs.mkdirSync(config.logging.directory, { recursive: true });
  }

  // Create a write stream for file logging (in append mode)
  const accessLogStream = fs.createWriteStream(
    path.join(config.logging.directory, 'access.log'), 
    { flags: 'a' }
  );

  // Log to console and file
  app.use(morgan(config.logging.level));
  app.use(morgan(config.logging.level, { stream: accessLogStream }));

  console.log(`Logging enabled. Level: ${config.logging.level}, Directory: ${config.logging.directory}`);
}

// ========== ROUTES ==========

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: config.server.environment,
    uptime: process.uptime(),
    app: config.app.name,
    version: config.app.version,
  });
});

app.get('/users', [
  // Validation using configurable limits
  body('page').optional().isInt({ min: 1 }),
  body('limit').optional().isInt({ 
    min: 1, 
    max: config.app.maxPageSize 
  }).withMessage(`Limit must be between 1 and ${config.app.maxPageSize}`),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Get pagination parameters with defaults from config
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || config.app.defaultPageSize;
  const offset = (page - 1) * limit;

  // Simulated user data
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
    { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
    { id: 4, name: 'Diana', email: 'diana@example.com', role: 'user' },
    { id: 5, name: 'Eve', email: 'eve@example.com', role: 'user' },
  ];

  // Apply pagination (simulated - in real app, this would be a database query)
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      page,
      limit,
      total: users.length,
      totalPages: Math.ceil(users.length / limit),
      hasNext: offset + limit < users.length,
      hasPrev: page > 1,
    },
    config: {
      defaultPageSize: config.app.defaultPageSize,
      maxPageSize: config.app.maxPageSize,
    },
  });
});

// Configuration endpoint (protected in production)
app.get('/config', (req, res) => {
  if (config.server.isProduction && !config.features.debugMode) {
    return res.status(403).json({ 
      error: 'Configuration endpoint disabled in production' 
    });
  }

  // Return safe configuration (exclude secrets)
  const safeConfig = {
    server: {
      port: config.server.port,
      host: config.server.host,
      environment: config.server.environment,
    },
    security: {
      rateLimit: {
        enabled: config.features.enableRateLimiting,
        windowMinutes: config.security.rateLimit.windowMs / 60000,
        maxRequests: config.security.rateLimit.maxRequests,
      },
      cors: {
        enabled: config.features.enableCors,
        allowedOriginsCount: config.security.cors.allowedOrigins.length,
      },
      request: {
        bodyLimit: config.security.request.bodyLimit,
      },
    },
    app: {
      name: config.app.name,
      version: config.app.version,
      defaultPageSize: config.app.defaultPageSize,
      maxPageSize: config.app.maxPageSize,
    },
    features: {
      debugMode: config.features.debugMode,
      enableLogging: config.features.enableLogging,
    },
  };

  res.json(safeConfig);
});

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString(),
  });
});

// Global error handler
app.use((err, req, res, next) => {
  const timestamp = new Date().toISOString();
  const errorId = `err_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

  console.error(`[${timestamp}] [${errorId}] Error:`, err);

  const errorResponse = {
    error: 'Internal Server Error',
    message: 'An unexpected error occurred',
    timestamp,
    errorId, // For tracking in logs
  };

  // Include more details in non-production environments
  if (!config.server.isProduction || config.features.debugMode) {
    errorResponse.details = err.message;
    if (err.stack && config.features.debugMode) {
      errorResponse.stack = err.stack.split('\n').slice(0, 5); // Limit stack trace
    }
  }

  res.status(err.status || 500).json(errorResponse);
});

// ========== SERVER SETUP ==========

// Security: Don't expose server information in headers
app.disable('x-powered-by');

// Set timeouts from configuration
const server = app.listen(config.server.port, config.server.host, () => {
  console.log(`
  ========================================
  ${config.app.name} v${config.app.version}
  ========================================
  Environment: ${config.server.environment}
  Server: http://${config.server.host}:${config.server.port}
  Node: ${process.version}
  Platform: ${process.platform}/${process.arch}
  ========================================
  Features:
    - Rate Limiting: ${config.features.enableRateLimiting ? 'ENABLED' : 'DISABLED'}
    - CORS: ${config.features.enableCors ? 'ENABLED' : 'DISABLED'}
    - Logging: ${config.features.enableLogging ? 'ENABLED' : 'DISABLED'}
    - Debug Mode: ${config.features.debugMode ? 'ENABLED' : 'DISABLED'}
  ========================================
  `);
});

// Apply configured timeouts
server.timeout = config.timeouts.request;
server.keepAliveTimeout = config.timeouts.keepAlive;

// Graceful shutdown
const shutdown = (signal) => {
  console.log(`\n${signal} received, shutting down gracefully...`);

  server.close(() => {
    console.log('Server closed');

    // Close any other connections (database, Redis, etc.) here
    // Example: if (db) db.close();

    console.log('Cleanup complete. Exiting.');
    process.exit(0);
  });

  // Force shutdown after 10 seconds if graceful shutdown fails
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  shutdown('uncaughtException');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  shutdown('unhandledRejection');
});

module.exports = { app, server, config };

// ========== STARTUP VALIDATION ==========
console.log('Configuration loaded successfully:');
console.log(`  Environment: ${config.server.environment}`);
console.log(`  Server Port: ${config.server.port}`);
console.log(`  Server Host: ${config.server.host}`);
console.log(`  Body Limit: ${config.security.request.bodyLimit}`);
console.log(`  Rate Limit: ${config.security.rateLimit.maxRequests} req/${config.security.rateLimit.windowMs/60000}min`);

