const fs = require('fs');

// Read the app.js file
const content = fs.readFileSync('app.js', 'utf8');

// Analyze for hardcoded values
console.log('=== SECURITY ANALYSIS: Hardcoded Values ===\n');

// Find all string literals (simple regex approach)
const stringRegex = /(['"])(?:(?=(\\?))\2.)*?\1/g;
let match;
const strings = [];

while ((match = stringRegex.exec(content)) !== null) {
  strings.push(match[0]);
}

console.log('String literals found:');
strings.forEach((str, i) => {
  console.log(`  [${i}] ${str}`);
});

// Find numeric constants
const numberRegex = /\b\d+\b/g;
const numbers = [];
while ((match = numberRegex.exec(content)) !== null) {
  numbers.push(match[0]);
}

console.log('\nNumeric constants found:');
numbers.forEach(num => {
  console.log(`  ${num}`);
});

// Categorize findings
console.log('\n=== CATEGORIZATION OF HARCODED VALUES ===\n');

const issues = [];

// Check port number
if (content.includes('listen(3000)') || content.includes('port 3000')) {
  issues.push({
    type: 'CONFIGURATION',
    value: '3000',
    description: 'Hardcoded port number',
    recommendation: 'Should be environment variable PORT',
    severity: 'MEDIUM'
  });
}

// Check API endpoints
const endpoints = ['/health', '/users'];
endpoints.forEach(endpoint => {
  if (content.includes(endpoint)) {
    issues.push({
      type: 'ROUTE',
      value: endpoint,
      description: 'API endpoint path',
      recommendation: 'Consider making configurable if needed for different environments',
      severity: 'LOW'
    });
  }
});

// Check status messages
if (content.includes("'ok'")) {
  issues.push({
    type: 'RESPONSE',
    value: 'ok',
    description: 'Hardcoded response status',
    recommendation: 'Consider if this needs to be configurable',
    severity: 'LOW'
  });
}

// Check user data
if (content.includes('alice@example.com') || content.includes('bob@example.com')) {
  issues.push({
    type: 'TEST_DATA',
    value: 'Test email addresses',
    description: 'Hardcoded test user data',
    recommendation: 'Should come from database or environment variables in production',
    severity: 'MEDIUM'
  });
}

console.log('Security Issues Found:');
issues.forEach((issue, i) => {
  console.log(`\n${i + 1}. ${issue.type} ISSUE:`);
  console.log(`   Value: ${issue.value}`);
  console.log(`   Description: ${issue.description}`);
  console.log(`   Recommendation: ${issue.recommendation}`);
  console.log(`   Severity: ${issue.severity}`);
});

console.log('\n=== SUMMARY ===');
console.log(`Total issues found: ${issues.length}`);
console.log('MEDIUM severity issues need immediate attention (port configuration)');
