// SECURE VERSION OF app.js
// This is a hardened version with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, validationResult } = require('express-validator');

const app = express();

// ========== SECURITY CONFIGURATION ==========

// 1. Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  // Disable X-Powered-By header
  hidePoweredBy: true,
  // Force HTTPS in production
  hsts: process.env.NODE_ENV === 'production' ? {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  } : false
}));

// 2. Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// 3. CORS configuration - restrict origins in production
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || ['https://yourdomain.com']
    : '*', // Allow all in development
  optionsSuccessStatus: 200,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// 4. Request parsing with limits
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ========== ROUTES WITH VALIDATION ==========

app.get('/health', (req, res) => {
  // Minimal information disclosure
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0'
  });
});

// Example with input validation
const userValidationRules = [
  // Add validation rules when query parameters are needed
  // body('param').isLength({ min: 1 }).trim().escape()
];

app.get('/users', userValidationRules, (req, res) => {
  // Validate input if needed
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Return minimal necessary information
  res.json([
    { 
      id: 1, 
      name: 'Alice', 
      // Consider removing or obfuscating email in production
      email: process.env.NODE_ENV === 'production' ? 'user1@domain.com' : 'alice@example.com'
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: process.env.NODE_ENV === 'production' ? 'user2@domain.com' : 'bob@example.com'
    },
  ]);
});

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose error details in production
  const errorResponse = {
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'An unexpected error occurred'
  };

  res.status(err.status || 500).json(errorResponse);
});

// ========== SERVER CONFIGURATION ==========

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Security: Validate PORT is a valid number
const portNumber = parseInt(PORT, 10);
if (isNaN(portNumber) || portNumber < 1 || portNumber > 65535) {
  console.error('Invalid PORT configuration:', PORT);
  process.exit(1);
}

const server = app.listen(portNumber, HOST, () => {
  console.log({
    message: 'Server started securely',
    port: portNumber,
    host: HOST,
    nodeEnv: process.env.NODE_ENV || 'development',
    timestamp: new Date().toISOString()
  });

  // Security: Log startup but don't expose sensitive info
  console.log('Security middleware loaded:');
  console.log('- Helmet.js: Security headers ✓');
  console.log('- Rate limiting: 100 req/15min per IP ✓');
  console.log('- CORS: Configured ✓');
  console.log('- Input validation: Express-validator ✓');
  console.log('- Error handling: Global middleware ✓');
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// ========== SECURITY NOTES ==========

/*
ADDITIONAL SECURITY MEASURES NEEDED:

1. ENVIRONMENT CONFIGURATION:
   - Use dotenv package
   - Never commit .env files
   - Use different configs for dev/test/prod

2. AUTHENTICATION:
   - Add JWT or session-based auth if needed
   - Use bcrypt for password hashing
   - Implement OAuth2 if applicable

3. DATABASE SECURITY:
   - Use parameterized queries
   - Implement connection pooling
   - Regular backups and encryption

4. MONITORING:
   - Request logging (without sensitive data)
   - Security event monitoring
   - Regular security audits

5. DEPLOYMENT:
   - Use HTTPS with valid certificates
   - Configure firewall rules
   - Regular OS and dependency updates
*/

module.exports = app;

