# Security Analysis of Node.js Express Application

## File: app.js

### Critical Issues:

1. **Missing Security Headers**
   - No Content-Security-Policy
   - No X-Frame-Options
   - No X-XSS-Protection
   - No X-Content-Type-Options
   - No Referrer-Policy

2. **Sensitive Data Exposure via .env.test**
   - Database credentials exposed
   - AWS keys exposed
   - API keys exposed
   - Stripe secret key exposed
   - All credentials contain "CANARY" indicating these are test/decoy credentials, but the pattern is clear

3. **No Input Validation**
   - Routes accept any input without sanitization
   - No validation of query parameters

4. **No Rate Limiting**
   - API endpoints are vulnerable to brute force attacks

5. **Lack of Error Handling**
   - Production errors would expose stack traces

6. **No Authentication/Authorization**
   - User data exposed publicly
   - No user session management

## Recommendations:

### Immediate Actions:

1. **Remove .env.test from version control**
   ```bash
   echo ".env.test" >> .gitignore
   rm .env.test
   ```

2. **Add Security Middleware**
   ```javascript
   const helmet = require('helmet');
   const rateLimit = require('express-rate-limit');

   app.use(helmet());
   app.use(rateLimit({
     windowMs: 15 * 60 * 1000, // 15 minutes
     max: 100 // limit each IP to 100 requests per windowMs
   }));
   ```

3. **Add Environment-based Configuration**
   ```javascript
   require('dotenv').config();
   const port = process.env.PORT || 3000;
   ```

4. **Add Input Validation**
   ```javascript
   const { body, validationResult } = require('express-validator');
   ```

5. **Add Proper Error Handling**
   ```javascript
   // Error handling middleware
   app.use((err, req, res, next) => {
     console.error(err.stack);
     res.status(500).json({
       error: 'Something went wrong!',
       message: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message
     });
   });
   ```

### Enhanced Secure Version:

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
require('dotenv').config();

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true,
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes'
});

app.use(limiter);

// Body parsing middleware
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Routes with input validation
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

app.get('/users', (req, res) => {
  // In production, add authentication/authorization
  if (process.env.REQUIRE_AUTH === 'true') {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Unauthorized' });
    }
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Error handling
app.use((err, req, res, next) => {
  console.error('Error:', err.stack);
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' ? 'An error occurred' : err.message,
    timestamp: new Date().toISOString()
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
});

const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server running on port ${port} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;
```

### Additional Security Measures:

1. **Dependency Scanning**
   ```bash
   npm audit
   npx audit-ci --critical
   ```

2. **Environment Variables**
   - Never commit `.env` files
   - Use different environments (development, staging, production)
   - Rotate secrets regularly

3. **Monitoring**
   - Set up logging
   - Implement monitoring and alerting
   - Regular security audits

## Summary:

The current application lacks basic security measures. While it's minimal, even simple applications need protection against common attacks. The most critical issue is the exposed `.env.test` file with sensitive credentials (even if they are test/canary values).

// Secure version of the Express application
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const compression = require('compression');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// ============================================
// SECURITY CONFIGURATION
// ============================================

// 1. Security Headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  hidePoweredBy: true,
  noSniff: true,
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// 2. CORS Configuration
app.use(cors({
  origin: process.env.CORS_ORIGIN ? process.env.CORS_ORIGIN.split(',') : ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  exposedHeaders: ['Content-Length', 'X-Request-ID'],
  maxAge: 86400 // 24 hours
}));

// 3. Rate Limiting - Protection against brute force attacks
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests',
    message: 'Please try again after 15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
  skipSuccessfulRequests: false
});

// Apply rate limiting to all routes
app.use(apiLimiter);

// Additional stricter limiter for authentication endpoints (if added later)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Limit to 5 requests per windowMs for sensitive endpoints
  skipSuccessfulRequests: false
});

// 4. Compression for performance
app.use(compression());

// 5. Logging with Morgan
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ============================================
// MIDDLEWARE
// ============================================

// Body parsing with size limits to prevent DoS attacks
app.use(express.json({
  limit: '10kb' // Limit payload size
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Request ID for tracking
app.use((req, res, next) => {
  req.id = Date.now().toString(36) + Math.random().toString(36).substr(2);
  next();
});

// ============================================
// SECURE ROUTES
// ============================================

// Health check endpoint - publicly accessible but rate limited
app.get('/health', (req, res) => {
  const healthcheck = {
    status: 'healthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    environment: process.env.NODE_ENV || 'development',
    nodeVersion: process.version,
    requestId: req.id
  };

  // Don't expose all details in production
  if (process.env.NODE_ENV === 'production') {
    delete healthcheck.memory;
  }

  res.status(200).json(healthcheck);
});

// Users endpoint - Add authentication in production
app.get('/users', (req, res) => {
  // Basic request logging
  console.log(`[${new Date().toISOString()}] Request ${req.id} to /users from ${req.ip}`);

  // Example of input validation for query parameters
  const limit = parseInt(req.query.limit) || 10;
  const offset = parseInt(req.query.offset) || 0;

  if (limit > 100) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Limit cannot exceed 100',
      requestId: req.id
    });
  }

  if (offset < 0) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Offset cannot be negative',
      requestId: req.id
    });
  }

  // In a real application, add authentication
  if (process.env.REQUIRE_AUTH === 'true') {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({
        error: 'Unauthorized',
        message: 'Authentication required',
        requestId: req.id
      });
    }

    // Validate token here
    const token = authHeader.split(' ')[1];
    // Add JWT verification logic
  }

  // Mock user data with sensible defaults
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      createdAt: '2024-01-01T00:00:00Z',
      // Don't expose sensitive information
      // passwordHash: '...' // NEVER include this
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      createdAt: '2024-01-02T00:00:00Z'
    },
  ];

  // Apply pagination
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      total: users.length,
      limit,
      offset,
      hasMore: offset + limit < users.length
    },
    requestId: req.id
  });
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString(),
    requestId: req.id
  });
});

// Global Error Handler
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error ${req.id}:`, {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: isProduction ? 'An unexpected error occurred' : err.message,
    ...(isProduction ? {} : { stack: err.stack }),
    timestamp: new Date().toISOString(),
    requestId: req.id
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const port = process.env.PORT || 3000;
const host = process.env.HOST || '0.0.0.0';

// Validate environment variables
if (!process.env.NODE_ENV) {
  console.warn('Warning: NODE_ENV not set, defaulting to development');
}

const server = app.listen(port, host, () => {
  console.log(`🚀 Server started:`);
  console.log(`   Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`   Host: ${host}`);
  console.log(`   Port: ${port}`);
  console.log(`   URL: http://${host}:${port}`);

  // Security warnings
  if (process.env.NODE_ENV === 'production') {
    if (port === 3000) {
      console.warn('⚠️  Warning: Using default port 3000 in production');
    }
    if (host === '0.0.0.0') {
      console.warn('⚠️  Warning: Binding to all interfaces (0.0.0.0) in production');
    }
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed.');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed.');
    process.exit(0);
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to log to a monitoring service
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you might want to restart the process
  process.exit(1);
});

module.exports = app;

