#!/usr/bin/env node

/**
 * Environment Configuration Validator
 * Run this script to validate environment variables before starting the application
 */

require('dotenv').config();

const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m'
};

console.log(`${colors.bright}${colors.cyan}=== Environment Configuration Validation ===${colors.reset}\n`);

// Configuration schema for different environments
const configSchema = {
  development: {
    required: ['NODE_ENV'],
    recommended: ['PORT', 'HOST', 'CORS_ORIGIN'],
    warnings: {
      PORT: 'Using default port 3000 in development is acceptable',
      HOST: 'Using 0.0.0.0 exposes to all network interfaces',
    }
  },
  test: {
    required: ['NODE_ENV'],
    recommended: ['PORT', 'HOST'],
    warnings: {
      PORT: 'Consider using a different port than production',
    }
  },
  production: {
    required: ['NODE_ENV', 'PORT', 'HOST', 'JWT_SECRET'],
    recommended: ['DB_HOST', 'DB_USER', 'DB_PASSWORD', 'CORS_ORIGIN'],
    critical: [
      {
        condition: () => process.env.PORT === '3000',
        message: '⚠️  CRITICAL: Using default port 3000 in production is not recommended'
      },
      {
        condition: () => process.env.JWT_SECRET && process.env.JWT_SECRET.includes('your_jwt_secret'),
        message: '⚠️  CRITICAL: Using default JWT secret in production'
      },
      {
        condition: () => process.env.DB_PASSWORD && process.env.DB_PASSWORD === 'strong_password_here',
        message: '⚠️  CRITICAL: Using default database password in production'
      }
    ]
  }
};

// Get current environment
const env = process.env.NODE_ENV || 'development';
console.log(`${colors.bright}Environment: ${colors.yellow}${env}${colors.reset}\n`);

// Get schema for current environment
const schema = configSchema[env] || configSchema.development;

let hasErrors = false;
let hasWarnings = false;

// ============================================
// 1. Check required variables
// ============================================
console.log(`${colors.bright}${colors.blue}1. Required Environment Variables:${colors.reset}`);
if (schema.required && schema.required.length > 0) {
  schema.required.forEach(varName => {
    if (!process.env[varName]) {
      console.log(`  ${colors.red}✗ ${varName} is not set${colors.reset}`);
      hasErrors = true;
    } else {
      console.log(`  ${colors.green}✓ ${varName}=${maskSensitiveValue(varName, process.env[varName])}${colors.reset}`);
    }
  });
} else {
  console.log(`  ${colors.yellow}No required variables for ${env} environment${colors.reset}`);
}
console.log('');

// ============================================
// 2. Check recommended variables
// ============================================
console.log(`${colors.bright}${colors.blue}2. Recommended Environment Variables:${colors.reset}`);
if (schema.recommended && schema.recommended.length > 0) {
  schema.recommended.forEach(varName => {
    if (!process.env[varName]) {
      console.log(`  ${colors.yellow}⚠ ${varName} is not set (recommended for ${env})${colors.reset}`);
      hasWarnings = true;
    } else {
      console.log(`  ${colors.green}✓ ${varName}=${maskSensitiveValue(varName, process.env[varName])}${colors.reset}`);
    }
  });
} else {
  console.log(`  ${colors.yellow}No recommended variables for ${env} environment${colors.reset}`);
}
console.log('');

// ============================================
// 3. Check for critical issues
// ============================================
console.log(`${colors.bright}${colors.blue}3. Critical Security Checks:${colors.reset}`);
if (schema.critical && schema.critical.length > 0) {
  schema.critical.forEach(check => {
    if (check.condition()) {
      console.log(`  ${colors.red}✗ ${check.message}${colors.reset}`);
      hasErrors = true;
    }
  });
}

if (!schema.critical || schema.critical.length === 0) {
  console.log(`  ${colors.green}✓ No critical checks configured for ${env} environment${colors.reset}`);
}
console.log('');

// ============================================
// 4. Check for default/weak values
// ============================================
console.log(`${colors.bright}${colors.blue}4. Common Security Issues:${colors.reset}`);
checkForDefaultValues();
console.log('');

// ============================================
// Summary
// ============================================
console.log(`${colors.bright}${colors.cyan}=== Validation Summary ===${colors.reset}`);
console.log(`Environment: ${colors.yellow}${env}${colors.reset}`);

if (hasErrors) {
  console.log(`${colors.red}✗ Configuration has ERRORS - Application may not start or is UNSECURE${colors.reset}`);
  process.exit(1);
} else if (hasWarnings) {
  console.log(`${colors.yellow}⚠ Configuration has WARNINGS - Review recommendations above${colors.reset}`);
  console.log(`${colors.green}✓ Application can start${colors.reset}`);
} else {
  console.log(`${colors.green}✓ Configuration is VALID${colors.reset}`);
  console.log(`${colors.green}✓ Application can start safely${colors.reset}`);
}

// Helper function to mask sensitive values
function maskSensitiveValue(varName, value) {
  const sensitivePatterns = [
    'SECRET', 'KEY', 'PASSWORD', 'TOKEN', 'AUTH', 'CREDENTIAL'
  ];

  const isSensitive = sensitivePatterns.some(pattern => 
    varName.toUpperCase().includes(pattern)
  );

  if (isSensitive && value) {
    if (value.length <= 8) {
      return '****';
    }
    return value.substring(0, 4) + '****' + value.substring(value.length - 4);
  }

  return value || '(not set)';
}

// Function to check for default/weak values
function checkForDefaultValues() {
  const defaultChecks = [
    {
      var: 'PORT',
      value: process.env.PORT,
      defaults: ['3000', '8080', '8000'],
      message: 'Using common default port - consider changing for security'
    },
    {
      var: 'JWT_SECRET',
      value: process.env.JWT_SECRET,
      defaults: ['your_jwt_secret', 'secret', 'changeme', 'test'],
      message: 'Using weak/default JWT secret'
    },
    {
      var: 'DB_PASSWORD',
      value: process.env.DB_PASSWORD,
      defaults: ['password', '123456', 'admin', 'root', 'test'],
      message: 'Using weak/default database password'
    },
    {
      var: 'NODE_ENV',
      value: process.env.NODE_ENV,
      defaults: ['development'],
      message: 'Running in development mode'
    }
  ];

  let foundIssues = false;

  defaultChecks.forEach(check => {
    if (check.value && check.defaults.includes(check.value)) {
      console.log(`  ${colors.yellow}⚠ ${check.var}: ${check.message}${colors.reset}`);
      foundIssues = true;
    }
  });

  if (!foundIssues) {
    console.log(`  ${colors.green}✓ No default/weak values detected${colors.reset}`);
  }
}

// Check for exposed test credentials
function checkForTestCredentials() {
  console.log(`${colors.bright}${colors.blue}5. Test Credential Scan:${colors.reset}`);

  const testPatterns = [
    'test', 'example', 'demo', 'sample', 'mock',
    'CANARY', 'placeholder', 'changeme', 'dummy'
  ];

  let foundTestCreds = false;

  Object.keys(process.env).forEach(varName => {
    const value = process.env[varName];
    if (value && testPatterns.some(pattern => 
      value.toUpperCase().includes(pattern.toUpperCase())
    )) {
      console.log(`  ${colors.yellow}⚠ ${varName}: Contains test pattern "${testPatterns.find(p => value.toUpperCase().includes(p.toUpperCase()))}"${colors.reset}`);
      foundTestCreds = true;
    }
  });

  if (!foundTestCreds) {
    console.log(`  ${colors.green}✓ No test credentials detected${colors.reset}`);
  }
  console.log('');
}

// Run test credential check
checkForTestCredentials();

