// Fixed version with environment variables
// This demonstrates how to replace hardcoded values

const express = require('express');

// Load environment variables
require('dotenv').config();

const app = express();

// Configuration from environment variables with defaults
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';
const NODE_ENV = process.env.NODE_ENV || 'development';

// Log configuration on startup (be careful not to log secrets)
console.log(`
╔══════════════════════════════════════════╗
║     Application Configuration            ║
╠══════════════════════════════════════════╣
║ Environment: ${NODE_ENV.padEnd(30)} ║
║ Host:        ${HOST.padEnd(30)} ║
║ Port:        ${PORT.toString().padEnd(30)} ║
╚══════════════════════════════════════════╝
`);

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    uptime: process.uptime()
  });
});

// Users endpoint - in a real app, this would come from a database
// or external configuration
app.get('/users', (req, res) => {
  // Consider moving this data to environment-specific configuration
  // or a database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // In production, you might want to hide emails or add authentication
  if (NODE_ENV === 'production' && !req.headers['x-api-key']) {
    // Return users without email in production unless authenticated
    const safeUsers = users.map(user => ({
      id: user.id,
      name: user.name
    }));
    res.json(safeUsers);
  } else {
    res.json(users);
  }
});

// Start server with configured host and port
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running in ${NODE_ENV} mode on http://${HOST}:${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, closing server gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

// Configuration module with validation
// Demonstrates best practices for managing environment variables

const path = require('path');

// Load environment variables from .env file in development
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config({
    path: path.resolve(process.cwd(), '.env')
  });
}

// Configuration schema with defaults and validation
const config = {
  // Server configuration
  server: {
    port: parseInt(process.env.PORT) || 3000,
    host: process.env.HOST || '0.0.0.0',
    environment: process.env.NODE_ENV || 'development',
    isProduction: () => config.server.environment === 'production',
    isDevelopment: () => config.server.environment === 'development',
    isTest: () => config.server.environment === 'test',
  },

  // Security configuration
  security: {
    apiKey: process.env.API_KEY,
    corsOrigins: process.env.CORS_ORIGINS 
      ? process.env.CORS_ORIGINS.split(',') 
      : (config.server.isProduction() ? [] : ['http://localhost:3000', 'http://localhost:8080']),

    rateLimit: {
      windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes
      maxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
    },
  },

  // Database configuration (when added)
  database: {
    url: process.env.DATABASE_URL,
    pool: {
      min: parseInt(process.env.DB_POOL_MIN) || 2,
      max: parseInt(process.env.DB_POOL_MAX) || 10,
    },
  },

  // External services
  services: {
    api: {
      baseUrl: process.env.API_BASE_URL,
      timeout: parseInt(process.env.API_TIMEOUT) || 30000,
    },
    aws: {
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    },
  },

  // Logging configuration
  logging: {
    level: process.env.LOG_LEVEL || 'info',
    format: process.env.LOG_FORMAT || 'simple',
    enableRequestLogging: process.env.ENABLE_REQUEST_LOGGING !== 'false',
  },

  // Feature flags
  features: {
    newFeature: process.env.ENABLE_NEW_FEATURE === 'true',
    maintenanceMode: process.env.MAINTENANCE_MODE === 'true',
  },

  // Application settings
  application: {
    requestTimeout: parseInt(process.env.REQUEST_TIMEOUT) || 30000,
    responseTimeout: parseInt(process.env.RESPONSE_TIMEOUT) || 30000,
  },
};

// Validation function (basic example)
function validateConfig() {
  const errors = [];

  // Validate server port
  if (config.server.port < 1 || config.server.port > 65535) {
    errors.push(`Invalid port number: ${config.server.port}`);
  }

  // Validate environment
  const validEnvironments = ['development', 'test', 'production'];
  if (!validEnvironments.includes(config.server.environment)) {
    errors.push(`Invalid NODE_ENV: ${config.server.environment}. Must be one of: ${validEnvironments.join(', ')}`);
  }

  // Production-specific validations
  if (config.server.isProduction()) {
    if (!config.security.apiKey) {
      errors.push('API_KEY is required in production');
    }

    if (config.security.corsOrigins.length === 0) {
      errors.push('CORS_ORIGINS must be specified in production');
    }

    // Warn about development defaults in production
    if (config.server.port === 3000) {
      console.warn('⚠️  Warning: Using default port 3000 in production');
    }
  }

  // Development warnings
  if (config.server.isDevelopment()) {
    if (!config.security.apiKey) {
      console.warn('⚠️  Warning: No API_KEY set in development');
    }
  }

  return errors;
}

// Export configuration
module.exports = {
  config,
  validateConfig,

  // Helper functions
  getServerConfig: () => config.server,
  getSecurityConfig: () => config.security,
  getDatabaseConfig: () => config.database,
  getLoggingConfig: () => config.logging,
  getFeatureConfig: () => config.features,
};

